<?php $title='Bank Statements';require __DIR__.'/../layouts/header.php';$months=[1=>'Jan',2=>'Feb',3=>'Mar',4=>'Apr',5=>'May',6=>'Jun',7=>'Jul',8=>'Aug',9=>'Sep',10=>'Oct',11=>'Nov',12=>'Dec'];$businesses=[];if($clientId){$q=App\Core\Database::pdo()->prepare('SELECT id,business_name FROM businesses WHERE client_id=? AND status="active" ORDER BY business_name');$q->execute([$clientId]);$businesses=$q->fetchAll();}?>
<style>.bs-toolbar{display:flex;gap:12px;flex-wrap:wrap}.bs-toolbar label{display:grid;gap:5px}.bs-toolbar select,.bs-toolbar input,.bs-toolbar button,.upload-mini input{padding:8px;border:1px solid #cbd5e1;border-radius:7px}.upload-mini{display:grid;gap:4px}.upload-mini input[type=file]{width:160px}.month-box{min-width:86px}.missing{background:#fff7ed}.received{background:#f0fdf4}.muted2{color:#64748b;font-size:12px}.quick-actions{display:flex;gap:8px;flex-wrap:wrap}.mini-upload{margin-top:6px}</style>
<div class="pagehead"><div><h1>Bank Statements</h1><p>Automated monthly collection for bookkeeping preparation.</p></div></div>
<div class="panel"><form method="get" action="<?=route('bank-statements')?>" class="bs-toolbar"><label>Client<select name="client_id" onchange="this.form.submit()"><option value="">Select client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>" <?=$clientId===$c['id']?'selected':''?>><?=e($c['full_name'])?></option><?php endforeach;?></select></label><label>Year<input type="number" name="year" value="<?=$year?>" min="2000" max="2100"></label><button class="secondary">Load</button></form></div>
<?php if($clientId):?><div class="cards"><div class="card"><span>Accounts</span><strong><?=count($accounts)?></strong></div><div class="card"><span>Missing months</span><strong><?=count($missing)?></strong></div><div class="card"><span>Collection status</span><strong><?=$missing?'Needs attention':'Complete'?></strong></div><div class="card"><span>Automation</span><strong>Enabled</strong></div></div>
<div class="panel"><div class="quick-actions"><form method="post" action="<?=route('bank-statements.start-bookkeeping')?>"><?=csrf_field()?><input type="hidden" name="client_id" value="<?=$clientId?>"><input type="hidden" name="year" value="<?=$year?>"><select name="business_id"><option value="0">All / no specific business</option><?php foreach($businesses as $b):?><option value="<?=$b['id']?>"><?=e($b['business_name'])?></option><?php endforeach;?></select><button class="primary">Start Bookkeeping Automation</button></form><form method="post" action="<?=route('bank-statements.remind')?>"><?=csrf_field()?><input type="hidden" name="client_id" value="<?=$clientId?>"><input type="hidden" name="year" value="<?=$year?>"><button class="secondary">Generate Missing-Statement Reminder</button></form></div></div>
<div class="panel"><h2>Add bank account</h2><form method="post" action="<?=route('bank-statements.add-account')?>" class="form-grid"><?=csrf_field()?><input type="hidden" name="client_id" value="<?=$clientId?>"><input type="hidden" name="year" value="<?=$year?>"><label>Business<select name="business_id"><option value="">None</option><?php foreach($businesses as $b):?><option value="<?=$b['id']?>"><?=e($b['business_name'])?></option><?php endforeach;?></select></label><label>Bank name<input name="bank_name" required></label><label>Account last 4<input name="account_last4" maxlength="4" inputmode="numeric" required></label><label>Account type<select name="account_type"><option>checking</option><option>savings</option><option>credit</option><option>other</option></select></label><label class="wide">Internal note<input name="notes"></label><div class="wide"><button class="primary">Add Account</button></div></form></div>
<div class="panel table-wrap"><h2><?=$year?> monthly checklist</h2><table><thead><tr><th>Bank / Account</th><?php foreach($months as $m=>$label):?><th><?=$label?></th><?php endforeach;?><th>Missing</th></tr></thead><tbody><?php foreach($accounts as $a):?><tr><td><strong><?=e($a['bank_name'])?></strong><div class="muted2">Ending <?=e($a['account_last4']??'')?> · <?=e($a['business_name']??'No business')?></div></td><?php for($m=1;$m<=12;$m++):$v=$a['months'][$m]??null;?><td class="<?=$v&&$v['received']?'received':'missing'?>"><div><?=$v&&$v['received']?'✓':'—'?></div><?php if(!$v||empty($v['received'])):?><form class="upload-mini mini-upload" method="post" action="<?=route('bank-statements.upload')?>" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="client_id" value="<?=$clientId?>"><input type="hidden" name="bank_account_id" value="<?=$a['id']?>"><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="month" value="<?=$m?>"><input type="file" name="statement" accept="application/pdf,image/jpeg,image/png" required><button class="mini" title="Upload <?=$months[$m]?>">Upload</button></form><form method="post" action="<?=route('bank-statements.mark')?>"><?=csrf_field()?><input type="hidden" name="client_id" value="<?=$clientId?>"><input type="hidden" name="bank_account_id" value="<?=$a['id']?>"><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="month" value="<?=$m?>"><button class="mini">Mark</button></form><?php endif;?></td><?php endfor;?><td><span class="badge"><?=e($a['missing'])?></span></td></tr><?php endforeach;?></tbody></table></div>
<?php if($missing):?><div class="panel"><h2>Missing periods</h2><ul><?php foreach($missing as $m):?><li><?=e($months[$m['month']])?> <?=e($m['year'])?> — <?=e($m['bank_name'])?> ending <?=e($m['account_last4']?:'????')?></li><?php endforeach;?></ul></div><?php endif;?><?php endif;?><?php require __DIR__.'/../layouts/footer.php';?>
